import os as _os
_ROOT = _os.path.normpath(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), '..', '..', '..'))   # THE PORTABLE REPO (2026-09-15): the repo root from this file's own place
#!/usr/bin/env python3
# THE DEUTERONOMY WALK 14b (2026-09-23): THE LEAN EXAM FILE — the eight Mishnah rows the spine cites in its own Hebrew, read WHOLE from the export (Hebrew and
# English) at the design, each a case of a cell with its verdict; NO Talmud segment read (none needed — the disputed rows carry both arms on the Mishnah's own line);
# coverage COMPUTED from the export's rows, never recited. The docket whole OWED (COMPILE_DEBT's lean-pass box). NEVER Write a record without ls first (done). RUN FROM THE REPO ROOT.
import json, os, re, html, subprocess
ROOT = _ROOT
OUT = ROOT + '/logic/oral_triage/deu_16_reeh_shoftim_exam_2026-09-23.md'
assert not os.path.exists(OUT) or os.environ.get('DEU_REWRITE') == '1', OUT   # this sitting's own writer may rewrite its own ledger before the commit (DEU_REWRITE=1)
def clean(s): return re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', '', html.unescape(s))).strip()
def row(tr, c, p):
    d = f'{ROOT}/Data/sefaria_export/Mishnah_{tr}'
    he = json.load(open(f'{d}/he.json', encoding='utf-8')); en = json.load(open(f'{d}/en.json', encoding='utf-8'))
    g = lambda x: (x['text'] if isinstance(x, dict) and 'text' in x else x)
    return clean(g(he)[c - 1][p - 1]), clean(g(en)[c - 1][p - 1]).replace('halakha', 'halakha (the law)')   # the export's one transliterated term glossed for the lint
ROWS = [
 ('Berakhot', 1, 5, '16:3', "130:4 (the spine's own citation of the Mishnah's derivation — Ben Zoma's 'all the days of your life')", 'LAW', "F1 the_passover_at_the_place — the_night_remembered: TWO ARMS recorded as data — Ben Zoma's 'all' adds the nights (the exodus mentioned at night); the sages' 'all' adds the days of the Messiah; the verdict a DATA row, never the ink's", "מַזְכִּירִין יְצִיאַת מִצְרַיִם בַּלֵּילוֹת (the exodus from Egypt is mentioned at night)"),
 ('Pesachim', 3, 7, '16:3-4', "the leaven's removal against the Passover's own errands (the spine's 130-131 the ban and the seeing)", 'LAW', "F1 the_passover_at_the_place — the_leaven_on_the_road: THREE ARMS — return and remove when there is time to return to the errand; else nullify in the heart; to save from gentiles, a river, bandits, fire or a collapse — nullify; for an optional Sabbath residence — return at once; the removal's law by CALL to pesach.leaven_machine", "וְנִזְכַּר שֶׁיֶּשׁ לוֹ חָמֵץ בְּתוֹךְ בֵּיתוֹ (and he remembers that he has leaven in his house)"),
 ('Beitzah', 1, 1, '16:4', "131:3 (cited in the spine's own Hebrew — the two words two measures)", 'LAW', "F1 the_passover_at_the_place — the_two_measures: the House of Shammai leavening an olive and leaven a date, the House of Hillel both an olive — both arms recorded as data (the egg laid on a festival the row's first case, outside the chapter)", "שְׂאֹר בְּכַזַּיִת וְחָמֵץ בְּכַכּוֹתֶבֶת (leavening an olive and leaven a date)"),
 ('Sukkah', 1, 4, '16:13', "140:1-5 (the booth's making — the spine's rows on 'you shall make for yourself')", 'LAW', "F3 the_feast_of_booths — the_roofing: the trellised vine, gourd and ivy unfit unless cut or outnumbered by fit roofing; THE PRINCIPLE what is susceptible to impurity or grows not from the ground roofs nothing, what is not susceptible and grows from the ground roofs — a PARAMETER from the answer sheet", "כֹּל שֶׁהוּא מְקַבֵּל טֻמְאָה וְאֵין גִּדּוּלוֹ מִן הָאָרֶץ (whatever is susceptible to impurity and does not grow from the ground)"),
 ('Chagigah', 1, 1, '16:16', "143:1-5 (the times, the seeing, the males, the minors — the spine's rows)", 'LAW', "F4 the_three_pilgrimages — the_exempt_from_appearing: all obligated except the deaf-mute, the imbecile, the minor, the tumtum, the hermaphrodite, women, unfreed slaves, the lame, the blind, the sick, the old and one who cannot ascend on foot; THE MINOR two houses (the father's shoulders / the father's hand, 'three regalim' read at the feet) — a PARAMETER with the list and the two arms", "הַכֹּל חַיָּבִין בָּרְאִיָּה (all are obligated in the appearance)"),
 ('Chagigah', 1, 2, '16:16-17', "143:8 (the prices — the spine's row)", 'LAW', "F4 the_three_pilgrimages — the_two_amounts: Shammai the appearance two silver and the festival offering a ma'ah, Hillel the appearance a ma'ah and the festival offering two silver — both arms a PARAMETER", "הָרְאִיָּה שְׁתֵּי כֶסֶף וַחֲגִיגָה מָעָה כֶסֶף (the appearance two silver and the festival offering a ma'ah)"),
 ('Chagigah', 1, 4, '16:14-15', "141:2, 142:6 (cited in the spine's own Hebrew — 'Israel fulfil their duty with vows and freewill offerings')", 'LAW', "F3 the_feast_of_booths — the_joys_offering: Israelites fulfil the rejoicing with vows, freewill offerings and the cattle tithe; the priests with sin and guilt offerings, the firstborn, the breast and the thigh; not with birds nor meal offerings — a DATA row", "יִשְׂרָאֵל יוֹצְאִין יְדֵי חוֹבָתָן בִּנְדָרִים וּנְדָבוֹת (Israel fulfil their duty with vows and freewill offerings)"),
 ('Chagigah', 1, 5, '16:17', "143:9 (the Mishnah cited in the spine's own Hebrew — 'each man as the gift of his hand')", 'LAW', "F4 the_three_pilgrimages — the_gift_of_the_hand: many eaters and little property — many peace offerings and few burnt; much property and few eaters — the reverse; both few — the ma'ah and the two silver; both many — 'each man as the gift of his hand': a PARAMETER with the four cases", "מִי שֶׁיֵּשׁ לוֹ אוֹכְלִים מְרֻבִּים וּנְכָסִים מֻעָטִים (one who has many eaters and little property)"),
]
read = [(tr, c, p) + row(tr, c, p) for tr, c, p, *_ in ROWS]
for (tr, c, p, he, en), r in zip(read, ROWS):
    assert re.sub(r'[^א-ת]', '', r[7].split(' (')[0]) in re.sub(r'[^א-ת]', '', he), (tr, c, p, 'the opening typed from the row')   # the typed Hebrew opening found in the row's consonants
L = []
L.append("# THE LEAN EXAM — Deuteronomy 16:1-22 (the month of Aviv and the Passover at the place, the leaven and the bread of affliction, the night's flesh, the gates' bar, the evening and the sunset, the cooking and the morning, six days and the seventh's assembly; the weeks from the sickle, the feast of weeks with the hand's freewill measure, the rejoicing with the household, the slave remembered; the feast of booths seven days at the gathering, the rejoicing, the seven days at the place; the three pilgrimages of all the males, none empty, each as the gift of his hand; judges and officers in all the gates by the tribes, no wresting, no respecting of persons, no bribe, justice pursued; no asherah beside the altar, no pillar) — THE DEUTERONOMY WALK sitting 14b, THE LEAN PASS (2026-09-23; DEUTERONOMY_WALK.md \"Sitting 14b — THE COMPILE OF CHAPTER 16 … LEAN\" THE FORM)")
L.append("# DECLARED (THE LEAN PASS, owner-ruled 2026-09-23 — DEUTERONOMY_WALK.md \"THE LEAN PASS\"; the state doc's #208): NO DOCKET at this sitting — the testing shelf's cases are THE MISHNAH ROWS THE SPINE CITES IN ITS OWN HEBREW at the reading (logic/oral_triage/deu_16_reeh_shoftim_2026-09-23.md — rows 130:4, 131:3, 140:3, 142:6, 143:1-5, 143:8-9 and the finds), EIGHT rows: Mishnah Berakhot 1:5, Pesachim 3:7, Beitzah 1:1, Sukkah 1:4, Chagigah 1:1, 1:2, 1:4, 1:5 — each read WHOLE from the export (Data/sefaria_export/Mishnah_<tractate>/he.json and en.json, chapter:paragraph), Hebrew and English, at the design (the whole-row rule, owner-ruled 2026-09-17), each a case of a cell of cold_run_festivals_judges.py with its verdict a DATA row or a PARAMETER (the code/data separation law: the Mishnah's rows fed at run time, never written into the source). A TALMUD SEGMENT only where a Mishnah verdict is disputed and a cell needs it: NONE READ — the disputed rows (Beitzah 1:1, Chagigah 1:1's minor, 1:2) carry both houses' arms on the Mishnah's own line and the cells record both. THE FULL DOCKET OWED to the full process (COMPILE_DEBT.md's lean-pass box): the tractates the reading's finds name — Pesachim, Chagigah, Sukkah, Menachot 10, Rosh Hashanah 1, Moed Katan, Sanhedrin 1 and 4, Avodah Zarah 3; the segments Pesachim 28b, 68b, Chagigah 6a, 18a, Sukkah 9a, 48a, Menachot 65b-66a, Ketubot 105a-b, Sanhedrin 32a-b, Avodah Zarah 48a, Tamid 28b.")
L.append("# THE VERDICTS: LAW names the cell and the ask of cold_run_festivals_judges.py that grades the row (F1 the_passover_at_the_place, F3 the_feast_of_booths, F4 the_three_pilgrimages); the row's own words the case, the verdict the arms the Mishnah records. The Mishnah's rows by chapter:paragraph (the export's index).")
L.append("# COVERAGE (computed): %d of %d declared rows read whole (Hebrew %d, English %d); segments read 0; rows outside the chapter's verses 0 (Beitzah 1:1's egg the row's first clause, outside — the row read whole as the rule requires)." % (len(read), len(ROWS), sum(1 for r in read if r[3]), sum(1 for r in read if r[4])))
L.append("")
L.append("## THE EIGHT ROWS (each read whole; the verdict beside it)")
for (tr, c, p, he, en), (tr_, c_, p_, vs, where, verdict, cell, opening) in zip(read, ROWS):
    L.append("- Mishnah %s %d:%d — %s. On %s; %s. THE ROW (English, whole): %s THE HEBREW OPENS: %s. THE CELL: %s." % (tr, c, p, verdict, vs, where, en, opening, cell))
L.append("")
L.append("## CITE INDEX — every source opened, each fully named")
for tr, c, p, he, en in read:
    L.append("- Mishnah %s %d:%d (Data/sefaria_export/Mishnah_%s/he.json and en.json — chapter %d, paragraph %d; read whole)" % (tr, c, p, tr, c, p))
text = '\n'.join(L) + '\n'
open(OUT, 'w', encoding='utf-8').write(text)
print('THE LEAN EXAM WRITTEN: %s — %d bytes; %d rows read whole; segments read 0' % (OUT, len(text.encode()), len(read)))
